// Sin altas paradas el flujo termina solo: cero items y el nodo de correo no corre.
if (!items.length) return [];

// Agrupa las altas paradas por cliente y monta un resumen legible para el equipo.
// Esto es solo formato de presentación: ninguna regla de negocio vive en n8n.
const altas = $input.all().map((item) => item.json);

const porCliente = {};
for (const alta of altas) {
  (porCliente[alta.cliente] ??= []).push(alta);
}

const lineas = Object.entries(porCliente).map(([cliente, altasDeCliente]) => {
  const detalle = altasDeCliente
    .sort((a, b) => b.dias_parada - a.dias_parada)
    .map(
      (alta) =>
        `  - CUPS ${alta.cups} · estado ${alta.estado} · ${alta.dias_parada} días parada`,
    )
    .join('\n');
  return `- ${cliente} (${altasDeCliente.length} alta(s) parada(s)):\n${detalle}`;
});

const clientes = Object.keys(porCliente).length;
return [
  {
    json: {
      total_altas: altas.length,
      clientes_afectados: clientes,
      resumen: `Hay ${altas.length} alta(s) parada(s) desde hace más de 7 días, en ${clientes} cliente(s):\n\n${lineas.join('\n')}`,
    },
  },
];
